import os
import re
import subprocess
import requests

def chunk_text(text, max_chars=4000):
    """Split text into chunks at sentence boundaries."""
    # Try to split by sentence
    sentences = re.split(r'(?<=[.!?])\s+', text)
    chunks = []
    current_chunk = ""

    for sentence in sentences:
        if len(current_chunk) + len(sentence) < max_chars:
            current_chunk += sentence + " "
        else:
            if current_chunk:
                chunks.append(current_chunk.strip())
            current_chunk = sentence + " "

    if current_chunk:
        chunks.append(current_chunk.strip())

    return chunks

def create_with_openai(text, output_path):
    """Generate audiobook using OpenAI TTS API."""
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        print("Error: OPENAI_API_KEY not found")
        return False

    chunks = chunk_text(text, max_chars=4000)
    audio_files = []

    print(f"Splitting text into {len(chunks)} chunks")

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        print(f"Generating chunk {i+1}/{len(chunks)}...")

        response = requests.post(
            "https://api.openai.com/v1/audio/speech",
            headers={
                "Authorization": f"Bearer {api_key}",
                "Content-Type": "application/json"
            },
            json={
                "model": "tts-1",
                "input": chunk,
                "voice": "onyx",
                "response_format": "mp3"
            }
        )

        if response.status_code == 200:
            with open(chunk_file, "wb") as f:
                f.write(response.content)
            audio_files.append(chunk_file)
        else:
            print(f"Error: {response.status_code} - {response.text}")
            return False

    return concatenate_audio(audio_files, output_path)

def concatenate_audio(audio_files, output_path):
    """Concatenate multiple audio files using ffmpeg."""
    if not audio_files:
        return False

    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    print(f"Concatenating {len(audio_files)} files into {output_path}...")
    result = subprocess.run([
        "ffmpeg", "-y", "-f", "concat", "-safe", "0",
        "-i", list_file, "-c", "copy", output_path
    ], capture_output=True)

    # Cleanup temp files
    for f in audio_files:
        try:
            os.unlink(f)
        except:
            pass
    try:
        os.unlink(list_file)
    except:
        pass

    return result.returncode == 0

def main():
    all_text = ""

    # Read ds.txt
    if os.path.exists('ds.txt'):
        with open('ds.txt', 'r') as f:
            text = f.read()
        all_text += "Do Things that Don't Scale. By Paul Graham.\n\n" + text + "\n\n"

    # Read foundermode.txt
    if os.path.exists('foundermode.txt'):
        with open('foundermode.txt', 'r') as f:
            text = f.read()
        all_text += "Founder Mode. By Paul Graham.\n\n" + text

    if not all_text:
        print("No text found to convert!")
        return

    print(f"Total text length: {len(all_text)} characters")

    output_file = "/root/audiobook.mp3"
    success = create_with_openai(all_text, output_file)

    if success:
        print(f"Audiobook created successfully at {output_file}!")
    else:
        print("Failed to create audiobook")

if __name__ == "__main__":
    main()

