            "model": "tts-1",
            "input": chunk,
            "voice": "onyx",
            "response_format": "mp3"
        }

        # Use curl to avoid dependency on requests
        cmd = [
            "curl", "-s", "https://api.openai.com/v1/audio/speech",
            "-H", f"Authorization: Bearer {api_key}",
            "-H", "Content-Type: application/json",
            "-d", json.dumps(data),
            "--output", chunk_file
